interface Payment {
    String pay(int amountCents);
}

class WalletPayment implements Payment {
    public String pay(int amountCents) {
        return "Paiement portefeuille: " + amountCents;
    }
}

void checkout(Payment payment, int amountCents) {
    System.out.println(payment.pay(amountCents)); // ne connaît aucune implémentation concrète
}

